class Solution:
    def countValidWordOccurrences(self, chunks: List[str], queries: List[str]) -> List[int]:
        s = "".join(chunks)
        cnt = {}
        i, n = 0, len(s)
        while i < n:
            if s[i].islower():
                j = i + 1
                while j < n and (s[j].islower() or (s[j] == '-' and j + 1 < n and s[j + 1].islower())):
                    j += 1
                w = s[i:j]
                cnt[w] = cnt.get(w, 0) + 1
                i = j
            else:
                i += 1
        return [cnt.get(q, 0) for q in queries]

