class Solution {
public:
    vector<int> countValidWordOccurrences(vector<string>& chunks, vector<string>& queries) {
        string s;
        for (auto& c : chunks) s += c;
        unordered_map<string, int> cnt;
        int i = 0, n = s.size();
        while (i < n) {
            if (islower(s[i])) {
                int j = i + 1;
                while (j < n && (islower(s[j]) || (s[j] == '-' && j + 1 < n && islower(s[j + 1])))) j++;
                cnt[s.substr(i, j - i)]++;
                i = j;
            } else i++;
        }
        vector<int> ans;
        for (auto& q : queries) ans.push_back(cnt.count(q) ? cnt[q] : 0);
        return ans;
    }
};

