class Solution {
    public int[] countValidWordOccurrences(String[] chunks, String[] queries) {
        StringBuilder sb = new StringBuilder();
        for (String c : chunks) sb.append(c);
        String s = sb.toString();
        Map<String, Integer> cnt = new HashMap<>();
        int i = 0, n = s.length();
        while (i < n) {
            char ch = s.charAt(i);
            if (ch >= 'a' && ch <= 'z') {
                int j = i + 1;
                while (j < n && ((s.charAt(j) >= 'a' && s.charAt(j) <= 'z') ||
                        (s.charAt(j) == '-' && j + 1 < n && s.charAt(j + 1) >= 'a' && s.charAt(j + 1) <= 'z'))) j++;
                cnt.merge(s.substring(i, j), 1, Integer::sum);
                i = j;
            } else i++;
        }
        int[] ans = new int[queries.length];
        for (int k = 0; k < queries.length; ++k) ans[k] = cnt.getOrDefault(queries[k], 0);
        return ans;
    }
}

