var countValidWordOccurrences = function(chunks, queries) {
    const s = chunks.join('');
    const cnt = new Map();
    const isL = c => c >= 'a' && c <= 'z';
    let i = 0;
    while (i < s.length) {
        if (isL(s[i])) {
            let j = i + 1;
            while (j < s.length && (isL(s[j]) || (s[j] === '-' && j + 1 < s.length && isL(s[j + 1])))) j++;
            const w = s.slice(i, j);
            cnt.set(w, (cnt.get(w) || 0) + 1);
            i = j;
        } else i++;
    }
    return queries.map(q => cnt.get(q) || 0);
};

