class Solution {
public:
    vector<int> countValidWordOccurrences(vector<string>& chunks, vector<string>& queries) {
        string s;
        for (auto& c : chunks) s += c;
        regex word("[a-z]+(?:-[a-z]+)*");
        unordered_map<string, int> cnt;
        auto begin = std::sregex_iterator(s.begin(), s.end(), word);
        auto end = std::sregex_iterator();
        for (auto it = begin; it != end; ++it) cnt[it->str()]++;
        vector<int> ans;
        for (auto& q : queries) ans.push_back(cnt.count(q) ? cnt[q] : 0);
        return ans;
    }
};

