class Solution {
    public int[] countValidWordOccurrences(String[] chunks, String[] queries) {
        StringBuilder sb = new StringBuilder();
        for (String c : chunks) sb.append(c);
        Matcher m = Pattern.compile("[a-z]+(?:-[a-z]+)*").matcher(sb.toString());
        Map<String, Integer> cnt = new HashMap<>();
        while (m.find()) cnt.merge(m.group(), 1, Integer::sum);
        int[] ans = new int[queries.length];
        for (int k = 0; k < queries.length; ++k) ans[k] = cnt.getOrDefault(queries[k], 0);
        return ans;
    }
}

